CREATE OR REPLACE FUNCTION public.revoke_chat_group_membership_on_community_leave() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.community_salon_members m USING public.community_salons s WHERE m.salon_id=s.id AND s.community_id=OLD.community_id AND m.user_id=OLD.user_id; DELETE FROM public.community_salon_join_requests r USING public.community_salons s WHERE r.salon_id=s.id AND s.community_id=OLD.community_id AND r.user_id=OLD.user_id; RETURN OLD; END; $$; DROP TRIGGER IF EXISTS trg_revoke_chat_group_membership_on_community_leave ON public.community_members; CREATE TRIGGER trg_revoke_chat_group_membership_on_community_leave AFTER DELETE ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.revoke_chat_group_membership_on_community_leave(); REVOKE ALL ON FUNCTION public.revoke_chat_group_membership_on_community_leave() FROM PUBLIC,anon,authenticated;